import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as i}from"./chunks/ON.DXVlsWbj.js";import{_ as o}from"./chunks/M-S-NL4.PyU7auYU.js";import{_ as a,o as r,c as s,a3 as n}from"./chunks/framework.g9mfNVRQ.js";const w=JSON.parse('{"title":"NightLite iOS follower","description":"","frontmatter":{},"headers":[],"relativePath":"use/nightlite.md","filePath":"use/nightlite.md"}'),l={name:"use/nightlite.md"};function p(c,t,h,d,u,m){return r(),s("div",null,[...t[0]||(t[0]=[n('<p>NightLite is a lightweight, Nightscout-compatible follower service. It&#39;s a simpler alternative to running your own Nightscout site when all you need is to share your BG with followers.</p><p>xDrip is the <strong>master</strong> (it uploads your data). The <a href="https://apps.apple.com/us/app/nightlite/id6759909591" target="_blank" rel="noreferrer">NightLite iOS app</a> (a fork of Nightguard, by Richard Lander) is the <strong>follower</strong> and displays your data on iPhone, iPad, Apple Watch or Mac.</p><div class="info custom-block"><p class="custom-block-title">Fun fact</p><p>xDrip only sends the last 12 hours of BG readings (with trend and delta) and treatments, refreshed with each new reading (about every 5 minutes).</p></div><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>xDrip on a recent <a href="./../install/download.html#pre-release">nightly</a> (minimum <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.03.01" target="_blank" rel="noreferrer">1st Mar 2026</a>).</li><li>A NightLite URL for your account. It contains your security key and is the only thing you need to enter: xDrip builds the follower QR code from it.</li><li>For the follower: an iPhone or iPad (iOS 15+), Apple Watch (watchOS 9.1+) or Mac (macOS 12 with M1 or later) running the <a href="https://apps.apple.com/us/app/nightlite/id6759909591" target="_blank" rel="noreferrer">NightLite app</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>NightLite cannot be used while xDrip runs as a <a href="./../install/nightscoutfollower.html">Nightscout follower</a>. It only works when xDrip is your primary data source.</p></div><h3 id="setup-the-master-xdrip" tabindex="-1">Set up the master (xDrip) <a class="header-anchor" href="#setup-the-master-xdrip" aria-label="Permalink to &quot;Set up the master (xDrip) {#setup-the-master-xdrip}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_cloud_upload_grey600_48dp.png" style="width:5%;"> Cloud Upload<br>   NightLite</p></div><p>Enter your NightLite URL:</p><div class="admonition xdripitem"><p class="admonition-title">NightLite URL</p><p> Typically entered by scanning QR code from dashboard<br>  This contains your security key - do not disclose it</p></div><p>Then enable the upload:</p><div class="admonition xdripitem"><p class="admonition-title">Upload to NightLite<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Whether to upload to the remote service</p></div><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>The NightLite URL contains your security key. Anyone with it can access your data, so don&#39;t share it.</p></div><h3 id="connect-a-follower" tabindex="-1">Connect a follower <a class="header-anchor" href="#connect-a-follower" aria-label="Permalink to &quot;Connect a follower&quot;">​</a></h3><p>Once the upload is enabled, xDrip can display a QR code that carries your whole configuration. This is what your follower scans; there&#39;s nothing to type on the follower device.</p><div class="admonition xdripitem"><p class="admonition-title">Show QR Code</p><p> Barcode for followers to scan to auto-configure them</p></div><ol><li>Install the <a href="https://apps.apple.com/us/app/nightlite/id6759909591" target="_blank" rel="noreferrer">NightLite app</a> on the follower device.</li><li>On the master phone, tap <strong>Show QR Code</strong>. xDrip displays the <code>NightLite configuration</code> QR code.</li><li>In the NightLite app preferences, tap the scan icon next to the Nightscout URL box and scan the QR code from the master&#39;s screen.</li></ol><img src="'+o+'" style="zoom:33%;"><div class="info custom-block"><p class="custom-block-title">Note</p><p>The NightLite service can send notifications back to xDrip and can remotely stop the upload if needed.</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',21)])])}const _=a(l,[["render",p]]);export{w as __pageData,_ as default};
